import{_ as t,l as c,o as l,c as n,v as s,p as h,x as d,d as o,i,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"101 Formulaic Alphas","description":"","frontmatter":{"title":"101 Formulaic Alphas","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/kakushadze-101-alphas.md","filePath":"quant/kakushadze-101-alphas.md","lastUpdated":1789023840000}'),u={name:"quant/kakushadze-101-alphas.md"};function m(E,e,A,k,B,g){const r=c("Mermaid");return l(),n("div",null,[e[1]||(e[1]=s('<h1 id="_101-formulaic-alphas" tabindex="-1">101 Formulaic Alphas <a class="header-anchor" href="#_101-formulaic-alphas" aria-label="Permalink to &quot;101 Formulaic Alphas&quot;">​</a></h1><div class="epigraph"><p>我们给出 101 个真实量化交易 alpha 的显式公式——它们同时也是计算机代码。平均持有期大约在 0.6 到 6.4 天；两两相关均值只有 15.9%。</p><footer>—— Kakushadze, 101 Formulaic Alphas, Wilmott Magazine, 2016；arXiv:1601.00991</footer></div><p>Zura Kakushadze 在 2016 年把 WorldQuant 许可使用的 101 条公式化 alpha 公开成可复制的表达式。它们大多是价量（开高低收、成交量、VWAP、收益），少数用市值或行业分类做中性。持有期短、相关低、收益与波动强相关而与换手无关——这组经验事实直接确认了 Kakushadze 与 Tulchinsky（2015）对四千条实盘 alpha 的间接结论。本篇把 101 式当作<strong>可审计的短持有因子语法</strong>：算子、delay-0 / delay-1、行业中性与「魔法数字」，而不是当作 2016 年之后仍可原样交易的信号清单。Harvey、Liu 与 Zhu 的多重检验、以及公开后的拥挤，都会改写这些公式的经济含义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公式化 alpha 要回答的不是「市场有没有可预测性」，而是：在价量算子的闭包里，什么样的表达式曾经构成可交易的预期收益，以及它们之间是否高度共线。公开数据里很少能看见真实交易式；学术因子又往往是月频、长持有、用账面与盈利。两者中间缺一块：<strong>日频、持有数日、用 <code>rank</code>、<code>ts_rank</code>、<code>correlation</code>、<code>decay_linear</code> 拼起来的短 alpha</strong>。Kakushadze 填的是这块。定义上，他沿用交易员口径：alpha 是「任何合理的预期收益指令」，不必等于资产定价里相对因子模型的截距。</p><p>挑战立刻出现。表达式是可复制的，生产配置不是：宇宙、行业分类版本、VWAP 口径、涨跌停与停牌处理、以及那些看起来像优化残留的非整数窗长（例如 <code>3.92795</code>）。把附录 A 逐条丢进 pandas 而不锁这些选择，得到的不是论文里的 101 条，而是另一族相关的技术指标。更严重的是<a href="/quant/look-ahead-bias">前视</a>：<code>delay-0</code> 用当日开盘或当日 VWAP，意味着交易必须发生在该信息已知之后；用收盘价假装在开盘成交，是把 delay-0 做成了不可实现的 delay 负值。</p><h3 id="均值回复块与动量块不是互斥分类" tabindex="-1">均值回复块与动量块不是互斥分类 <a class="header-anchor" href="#均值回复块与动量块不是互斥分类" aria-label="Permalink to &quot;均值回复块与动量块不是互斥分类&quot;">​</a></h3><p>粗分类里，均值回复 alpha 与它所基于的收益异号；动量 alpha 同号。简单 delay-0 回复可以写成 \\(-\\ln(\\text{今开}/\\text{昨收})\\)，希望开盘跳空被吐回；简单 delay-1 动量可以写成 \\(\\ln(\\text{昨收}/\\text{昨开})\\)，希望昨日日内趋势延续。复杂式把两种块嵌套：<code>rank</code>、<code>delta</code>、<code>correlation</code> 可以让同一条公式在某些股票上像回复、在另一些上像动量。Alpha#101 是 delay-1 动量：若日内收盘高于开盘且高低价差为正，次日做多。Alpha#42 本质是 delay-0 回复：<code>rank(vwap - close)</code> 在尾盘相对 VWAP 拉升时变低。读 101 式应拆成块，而不是给整条贴一张「动量/反转」标签。</p><p><span class="marginnote">论文明确说这些式子是按「能写进一篇文章」挑的简单子集；还存在大量无法公式化、只能以代码存在的 alpha。把 101 当成 WorldQuant 的完整因子库，是把演示样本当成总体。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>输入与算子。</strong> 字段包括 <code>open, high, low, close, volume, vwap, returns</code>，以及 <code>adv20</code> 一类平均成交量、<code>cap</code>、行业中性 <code>IndNeutralize</code>。截面算子：<code>rank</code> 把当天截面映到 \\((0,1)\\)，<code>scale</code> 把仓位和归一。时间序列算子：<code>delay</code>、<code>delta</code>、<code>ts_min/max</code>、<code>ts_argmin/argmax</code>、<code>ts_rank</code>、<code>sum</code>、<code>stddev</code>、<code>decay_linear</code>（过去 \\(d\\) 日线性衰减权重并归一）、<code>correlation</code> 与 <code>covariance</code>。条件用三元 <code>? :</code>。行业中性针对 GICS / BICS 等不同粒度；论文强调不同分类的「行业」层级名词并不一一对应，复制时必须固定一份分类 vintage。</p><p><strong>Delay 与可交易日历。</strong> Delay-0：公式里最新价格的时点与拟交易时点重合，现实中只能尽量靠近。Delay-1：用截至昨日的数据，今日开盘或全日交易。Delay-\\(d\\) 类推。A 股还要叠 <a href="/quant/cn-tplus1">T+1</a> 与涨跌停：delay-0 开盘回复在涨停打开前可能无法买入。评价应使用当时可成交价，而不是复权后的研究用价格，见<a href="/quant/corporate-actions">公司行为</a>。</p><p><strong>经验事实（论文第 3 节）。</strong> 在作者提供的夏普、换手、每股美分与样本协方差上：平均（中位）两两相关 15.9%（14.3%）；收益 \\(R\\) 与波动 \\(\\sigma\\) 满足近似幂律 \\(R\\sim\\sigma^{0.76}\\)；收益对换手没有显著依赖。换手本身对 alpha 之间的相关解释力差：\\(\\mathrm{corr}_{ij}\\) 与 \\(\\ln\\tau_i\\ln\\tau_j\\) 并不高度同向。这不是说换手在协方差因子模型里没有用，而是说「换手相近 \\(\\Rightarrow\\) 信号共线」这条捷径不成立。</p><h3 id="从单式到-mega-alpha" tabindex="-1">从单式到 mega-alpha <a class="header-anchor" href="#从单式到-mega-alpha" aria-label="Permalink to &quot;从单式到 mega-alpha&quot;">​</a></h3><p>Kakushadze 的引言把当代量化写成两股力量：单条 alpha 越来越弱、越来越短命；同时自动化让 alpha 数量膨胀到十万、百万。组合它们得到 mega-alpha，内部对倒降低成本，并分散「某一子集突然失效」。样本协方差在 \\(N\\gg T\\) 时奇异，这把问题接到因子协方差与收缩，而不是接到「再挖第 102 条」。公开 101 条之后，正确的研究问题是：在<a href="/quant/cs-rank-features">截面 rank</a> 与行业中性之后，它们对标准动量、短期反转、流动性的增量 \\(R^2\\) 还有多少；以及在扣<a href="/quant/spread-cost">有效价差</a> 后持有 0.6–6.4 天是否仍过零。</p><p><span class="marginnote">非整数窗长是优化痕迹。复制时应把 <code>3.92795</code> 当成已冻结的超参，而不是再在同一测试段上搜附近的实数。那会把 101 条变成 101 次新的<a href="/quant/harvey-liu-zhu">多重检验</a>。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价量公式能有预期收益，机制通常是微观结构与行为，而不是宏观风险：开盘跳空的过度反应、价量背离、尾盘相对 VWAP 的拉动、行业内相对强弱。<code>correlation(rank(delta(log(volume))), rank((close-open)/open))</code> 一类式子捕捉的是「价与量是否同向」；负号把它变成背离交易。<code>ts_rank</code> 把绝对变化变成「在自己近期历史上的分位」，从而对波动水平更不敏感——这与论文发现的「收益跟波动走、不跟换手走」相容：波动高的名字上，同样的分位对应更大的美元收益。</p><p>低两两相关来自算子组合的多样性，而不是来自正交化定理。101 条仍共享价量宇宙与短持有，对共同流动性冲击会一起受伤。换手解释不了相关，是因为两条低换手公式可以一个做开盘回复、一个做五日动量，持仓重叠不必高。反过来，两条高换手公式若都在追同一分钟的 OFI，相关会高——但 101 条是日频公式，看不见那一层。</p><p>公开之后的机制变化更重要。公式一旦成为标准特征，拥挤把原来的误定价压成风险：短期反转容量下降，残差转到尚未公式化的交互或更高频的队列。把 2016 年的夏普当作 2026 年的 \\(\\mu\\)，是把论文里的历史对象当成了 Kelly 公式里的参数。</p><h3 id="中国市场与算子语义" tabindex="-1">中国市场与算子语义 <a class="header-anchor" href="#中国市场与算子语义" aria-label="Permalink to &quot;中国市场与算子语义&quot;">​</a></h3><p>A 股的涨跌停让 <code>ts_max(close)</code> 经常顶在限制价，<code>correlation(close, volume)</code> 在封板日变成「量与一个常数」的相关。<code>vwap</code> 在集合竞价与午间休市上的定义必须与交易所一致。行业中性若用申万而论文用 BICS，中性后的残差不是同一对象。Leippold、Wang 与 Zhou（2022）在 A 股机器学习可预测性上的警告这里同样适用：不可交易日应在损失里视为不可实现，否则公式会去拟合涨停余波。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 101 条等权合成一个「WorldQuant 因子」再报告一个夏普：相关 15.9% 仍会在压力周共动，且等权忽略了各自波动。不要在全样本上调窗长再声称复制成功。不要用后复权价计算 <code>close &lt; 5</code> 一类过滤。容量上，持有不到一周的价量信号对<a href="/quant/sqrt-impact">冲击</a>极度敏感；论文的 cents-per-share 是当时、当时宇宙上的描述统计，不是你的成交价。</p><p>可审计性是这批公式相对黑箱模型的真正优点：每一条都能写成算子树，便于<a href="/quant/research-sim-prod">研究与实盘隔离</a>时做特征冻结。缺点是语法纵容组合爆炸——<code>rank</code> 套 <code>ts_rank</code> 套 <code>decay_linear</code> 可以无限长。搜索应预指定算子预算与<a href="/quant/label-horizon-overlap">标签重叠</a>规则，并把试验次数记进 Harvey–Liu–Zhu 的 \\(M\\)。</p><p><span class="marginnote">「公式即代码」只在同一解释器下成立。<code>rank</code> 对并列的处理、<code>correlation</code> 在常数输入上的返回值、停牌日是否进入 <code>adv20</code>，都会让两条「同一公式」的实现分叉。复制论文应同时冻结算子语义说明书。</span></p>',26)),(l(),h(p,null,{default:d(()=>[i(r,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20PV%5B%22OHLCV%20%2F%20VWAP%20%2F%20%E8%A1%8C%E4%B8%9A%22%5D%20--%3E%20OPS%5B%22rank%20%2F%20ts_rank%20%2F%20corr%20%2F%20decay%22%5D%0A%20%20OPS%20--%3E%20D0%5B%22delay-0%EF%BC%9A%E4%BA%A4%E6%98%93%E6%97%B6%E7%82%B9%E5%AF%B9%E9%BD%90%22%5D%0A%20%20OPS%20--%3E%20D1%5B%22delay-1%EF%BC%9A%E6%AC%A1%E6%97%A5%E5%8F%AF%E4%BA%A4%E6%98%93%22%5D%0A%20%20D0%20--%3E%20NEUT%5B%22%E8%A1%8C%E4%B8%9A%E4%B8%8E%E8%A7%84%E6%A8%A1%E4%B8%AD%E6%80%A7%22%5D%0A%20%20D1%20--%3E%20NEUT%0A%20%20NEUT%20--%3E%20COMBO%5B%22%E4%BD%8E%E7%9B%B8%E5%85%B3%E5%90%88%E6%88%90%20mega-alpha%22%5D%0A%20%20COMBO%20--%3E%20COST%5B%22%E6%8D%A2%E6%89%8B%E3%80%81%E4%BB%B7%E5%B7%AE%E3%80%81%E5%86%B2%E5%87%BB%22%5D%0A%20%20COST%20--%3E%20OOS%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%20IR%EF%BC%8C%E8%80%8C%E9%9D%9E%E5%85%AC%E5%BC%8F%E6%B8%85%E5%8D%95%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[o("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"Kakushadze（2016）公开 101 条价量为主的公式化 alpha：持有约 0.6–6.4 天，两两相关均值 15.9%，收益随波动缩放、与换手无关。"),a("li",null,"算子闭包（截面 rank、时序 rank、衰减、相关、行业中性）是短持有 alpha 的语法；delay-0 / delay-1 决定信息集是否可交易。"),a("li",null,"低相关不自动等于可加杠杆；公开后拥挤与成本会收走历史夏普。窗长与行业分类必须冻结。"),a("li",null,"A 股须把涨跌停、T+1 与停牌写进算子语义，否则是在拟合不可成交路径。"),a("li",null,[o("出处：Kakushadze, "),a("em",null,"101 Formulaic Alphas"),o(", Wilmott Magazine 2016(84):72–80，arXiv:1601.00991；经验对照见 Kakushadze and Tulchinsky, 2015。")])],-1))])}const q=t(u,[["render",m]]);export{_ as __pageData,q as default};
